def main() -> None:
    path = Path(__file__).resolve().parents[1] / "docs" / REPORT_NAME
    doc = Document(path)
    changed = False

    for paragraph in doc.paragraphs:
        text = paragraph.text
        for old, new in REPLACEMENTS.items():
            if old in text:
                text = text.replace(old, new)
        if text != paragraph.text:
            paragraph.text = text
            changed = True

    marker = "\u9879\u76ee\u7ec4\u81ea\u67e5\u540c\u6b65\u8865\u5145"
    full_text = "\n".join(paragraph.text for paragraph in doc.paragraphs)
    if marker not in full_text:
        doc.add_page_break()
        doc.add_heading(marker, level=1)
        for title, body in SUPPLEMENT:
            doc.add_heading(title, level=2)
            doc.add_paragraph(body)
        changed = True
    else:
        for title, body in SUPPLEMENT:
            if title not in full_text:
                doc.add_heading(title, level=2)
                doc.add_paragraph(body)
                changed = True

    if changed:
        doc.save(path)
        print(f"updated {path.name}")
    else:
        print(f"skipped {path.name}: already current")


if __name__ == "__main__":
    main()
